const portfolioLanguages = [{"attrs": {"content": {"zh": "毛雨晴的作品集：产品规划、AI 开发、用户运营与团队协作中的真实项目。", "en": "Yuqing Mao’s portfolio: real projects in product planning, AI development, user operations and collaborative problem solving."}}, "id": "0"}, {"text": {"en": "Yuqing Mao · Portfolio", "zh": "毛雨晴 · 作品集"}, "id": "1"}, {"attrs": {"content": {"zh": "毛雨晴 · 作品集", "en": "Yuqing Mao · Portfolio"}}, "id": "2"}, {"attrs": {"content": {"zh": "AI、产品开发与用户运营项目，包含原始证据和可体验原型。", "en": "Projects in AI, product development and user operations, with original evidence and working prototypes."}}, "id": "3"}, {"text": {"en": "Skip to main content", "zh": "跳到主要内容"}, "id": "4"}, {"attrs": {"aria-label": {"zh": "毛雨晴，回到顶部", "en": "Yuqing Mao, back to top"}}, "id": "5"}, {"text": {"en": "Yuqing Mao", "zh": "毛雨晴"}, "id": "6"}, {"attrs": {"aria-label": {"zh": "主导航", "en": "Main navigation"}}, "id": "7"}, {"text": {"en": "Projects", "zh": "项目作品"}, "id": "8"}, {"text": {"en": "Operations & Content", "zh": "运营与内容"}, "id": "9"}, {"text": {"en": "About", "zh": "关于我"}, "id": "10"}, {"text": {"en": "Let’s talk ", "zh": "聊聊机会 "}, "id": "11"}, {"tail": {"en": " Hi, I’m Yuqing Mao", "zh": " 你好，我是毛雨晴"}, "id": "12"}, {"text": {"zh": "所有问题，", "en": "Every problem"}, "id": "13"}, {"tail": {"zh": "都可以被", "en": "has a way "}, "id": "14"}, {"text": {"en": "Explore my projects ", "zh": "看我的项目 "}, "id": "17"}, {"text": {"en": "More about me ", "zh": "认识一下我 "}, "id": "18"}, {"text": {"en": "Class of 2027 ", "zh": "2027 届本科 "}, "id": "19"}, {"tail": {"en": " Automation Technology and Applications ", "zh": " 自动化技术与应用 "}, "id": "20"}, {"tail": {"en": " AI × Product × Operations", "zh": " AI × 产品 × 运营"}, "id": "21"}, {"attrs": {"aria-label": {"zh": "精选项目预览", "en": "Selected project previews"}}, "id": "22"}, {"text": {"en": "Turning ideas into working projects", "zh": "把想法做出来"}, "id": "23"}, {"attrs": {"alt": {"zh": "碳循花园花盆盲盒包装设计示意", "en": "Recycled-plastic planter and blind-box packaging concept (Chinese source)"}}, "id": "25"}, {"text": {"en": "Carbon Cycle Garden", "zh": "碳循花园"}, "id": "26"}, {"text": {"en": "Planter and packaging concepts", "zh": "花盆与包装设计"}, "id": "27"}, {"text": {"en": "GLIM", "zh": "GLIM / 碰见"}, "id": "29"}, {"text": {"en": "AI social interaction prototype", "zh": "AI 社交原型"}, "id": "30"}, {"attrs": {"alt": {"zh": "好时光功能示意：桌面显示当前计时，可快速开始、切换任务、暂停或结束", "en": "Good Time timer feature illustration, not an application screenshot (Chinese source)"}}, "id": "31"}, {"text": {"en": "Good Time", "zh": "Good Time · 好时光"}, "id": "32"}, {"text": {"en": "Desktop time tracker", "zh": "桌面计时工具"}, "id": "33"}, {"text": {"en": "Explore all projects ", "zh": "看看完整项目 "}, "id": "34"}, {"text": {"en": "Projects", "zh": "项目作品"}, "id": "35"}, {"text": {"en": "Physical product concept · Companion app", "zh": "实体产品方案 · 配套小程序"}, "id": "36"}, {"text": {"en": "Carbon Cycle Garden", "zh": "碳循花园"}, "id": "37"}, {"text": {"en": "Love your plants.", "zh": "想养花，"}, "id": "38"}, {"tail": {"en": " It’s okay to forget sometimes.", "zh": " 也要允许偶尔忘记。"}, "id": "39"}, {"text": {"zh": "想养花，又会忘记浇水。我们尝试用再生塑料做自吸水花盆，再配一个查养护、记成长的小程序。", "en": "For people who want plants but sometimes forget to water them: a recycled-plastic self-watering planter concept, paired with an app for care guidance and growth records."}, "id": "40"}, {"text": {"en": "Try the companion app ", "zh": "体验配套小程序 "}, "id": "45"}, {"text": {"en": "Recycled-plastic self-watering planter", "zh": "再生塑料自浇水花盆"}, "id": "47"}, {"text": {"en": "Product and companion services", "zh": "产品与配套服务"}, "id": "48"}, {"attrs": {"data-caption": {"zh": "花盆外观设计示意", "en": "Planter exterior concept · Original material in Chinese"}}, "id": "49"}, {"attrs": {"alt": {"zh": "再生塑料自浇水花盆外观设计", "en": "Planter exterior design concept (Chinese source)"}}, "id": "50"}, {"text": {"en": "Planter concept", "zh": "花盆外观"}, "id": "51"}, {"attrs": {"data-caption": {"zh": "花盆结构设计示意", "en": "Water storage and delivery concept · Original material in Chinese"}}, "id": "52"}, {"attrs": {"alt": {"zh": "花盆蓄水仓与导水结构", "en": "Water reservoir and capillary delivery structure concept (Chinese source)"}}, "id": "53"}, {"text": {"en": "Water storage and delivery", "zh": "储水与导水结构"}, "id": "54"}, {"text": {"en": "Companion app", "zh": "配套小程序"}, "id": "55"}, {"attrs": {"aria-label": {"zh": "放大查看养护小程序", "en": "Enlarge Carbon Cycle Garden companion app"}, "data-caption": {"zh": "碳循花园 · 配套小程序", "en": "Carbon Cycle Garden companion app · Original material in Chinese"}}, "id": "56"}, {"attrs": {"alt": {"zh": "碳循花园小程序的植物养护查询与成长记录界面", "en": "Companion app with plant-care lookup and growth records (Chinese source)"}}, "id": "57"}, {"text": {"en": "GLIM", "zh": "GLIM / 碰见"}, "id": "58"}, {"text": {"zh": "四个功能", "en": "Four features"}, "id": "59"}, {"attrs": {"aria-label": {"zh": "查看社交电量灯完整展板", "en": "Enlarge Social availability light"}, "data-caption": {"zh": "社交电量灯 · 绿灯开放连接，黄灯轻量连接，红灯暂不打扰。", "en": "Social availability light · Original material in Chinese"}}, "id": "60"}, {"attrs": {"alt": {"zh": "社交电量灯功能展板", "en": "GLIM social availability light: open, limited or unavailable for conversation (Chinese source)"}}, "id": "61"}, {"text": {"en": "Social availability light", "zh": "社交电量灯"}, "id": "62"}, {"attrs": {"aria-label": {"zh": "查看一键互助信号完整展板", "en": "Enlarge Help signal"}, "data-caption": {"zh": "一键互助信号 · 摇一摇切换互助信号，支持语音输入。", "en": "Help signal · Original material in Chinese"}}, "id": "64"}, {"attrs": {"alt": {"zh": "一键互助信号功能展板", "en": "GLIM help signal interface (Chinese source)"}}, "id": "65"}, {"text": {"en": "Ask for help", "zh": "一键互助信号"}, "id": "66"}, {"attrs": {"aria-label": {"zh": "查看AI 破冰完整展板", "en": "Enlarge AI icebreakers"}, "data-caption": {"zh": "AI 破冰 · 双方确认连接后，生成破冰话题。", "en": "AI icebreakers · Original material in Chinese"}}, "id": "68"}, {"attrs": {"alt": {"zh": "AI 破冰功能展板", "en": "GLIM AI-generated conversation starter interface (Chinese source)"}}, "id": "69"}, {"text": {"en": "AI icebreakers", "zh": "AI 破冰"}, "id": "70"}, {"attrs": {"aria-label": {"zh": "查看AI 交流复盘完整展板", "en": "Enlarge AI conversation review"}, "data-caption": {"zh": "AI 交流复盘 · 记录交流亮点与下次可以聊的话题。", "en": "AI conversation review · Original material in Chinese"}}, "id": "72"}, {"attrs": {"alt": {"zh": "AI 交流复盘功能展板", "en": "GLIM conversation review interface (Chinese source)"}}, "id": "73"}, {"text": {"en": "AI conversation review", "zh": "AI 交流复盘"}, "id": "74"}, {"text": {"en": "AI interaction · Hardware integration", "zh": "AI 交互 · 软硬件联调"}, "id": "76"}, {"text": {"en": "GLIM", "zh": "GLIM / 碰见"}, "id": "77"}, {"text": {"en": "I’d like to meet you.", "zh": "想认识你，"}, "id": "78"}, {"tail": {"en": " How do I start?", "zh": " 但第一句怎么说？"}, "id": "79"}, {"text": {"en": "At an in-person event, how can we signal openness to conversation while keeping the option not to be interrupted? Our wearable beacon and software prototype explore both needs.", "zh": "在一场线下活动里，怎样既表达社交意愿，又保留不被打扰的边界？我们用可穿戴信标与软件，尝试连接这两个需要。"}, "id": "80"}, {"text": {"en": "Try the interactive prototype ", "zh": "体验交互原型 "}, "id": "85"}, {"text": {"zh": "女性硬件黑客松作品。", "en": "Created at a women’s hardware hackathon."}, "id": "86"}, {"text": {"en": "Event operations · End-to-end delivery", "zh": "活动数字化 · 全流程交付"}, "id": "87"}, {"text": {"en": "Ningju Service Tour · Company Visits", "zh": "宁聚服务行 · 企业探访"}, "id": "88"}, {"text": {"en": "Bring the loose ends", "zh": "把活动现场的琐碎，"}, "id": "89"}, {"tail": {"en": " into one event workflow.", "zh": " 收进同一个流程。"}, "id": "90"}, {"text": {"en": "Check-in, photos and feedback were scattered across different steps. Working with a teacher’s event needs, I independently delivered the poster, QR entry point, participant interface and organizer dashboard.", "zh": "签到、收图、活动反馈，原本分散在不同环节。我面向老师的组织需求，独立完成活动海报、扫码入口、参与者页面与组织端后台。"}, "id": "91"}, {"text": {"en": "Delivered", "zh": "交付内容"}, "id": "92"}, {"text": {"en": "Check-in, photo wall, feedback and organizer dashboard", "zh": "签到、照片墙、反馈收集、组织端查看"}, "id": "93"}, {"text": {"en": "Open the event system ", "zh": "打开活动系统 "}, "id": "94"}, {"text": {"en": "From poster to participant interface", "zh": "从海报到活动页面"}, "id": "95"}, {"text": {"en": "Original materials and interface screenshots", "zh": "原始物料与界面截图"}, "id": "96"}, {"attrs": {"alt": {"zh": "宁聚服务行文化产业专场原始活动海报", "en": "Original company-visit event recruitment poster (Chinese source)"}}, "id": "97"}, {"text": {"en": "Event recruitment poster", "zh": "活动招募海报"}, "id": "98"}, {"attrs": {"alt": {"zh": "活动系统实际界面局部：行程、参访企业、上传打卡、照片墙、个人记录和活动反馈入口", "en": "Event participant interface with itinerary, photos and feedback (Chinese source)"}}, "id": "99"}, {"text": {"en": "Participant interface · Event tasks", "zh": "参与者页面 · 现场任务入口"}, "id": "100"}, {"text": {"en": "04 / Lujian · AI Accessibility", "zh": "04 / 路见 · AI 无障碍出行"}, "id": "101"}, {"text": {"en": "Help people with visual impairments", "zh": "希望视障人群，"}, "id": "102"}, {"tail": {"en": " feel more confident going out.", "zh": "能更安心地出门。"}, "id": "103"}, {"text": {"zh": "早期方案获 2026「工科女生未来赋能计划」全国总决赛第一名", "en": "Early concept: first place at the 2026 Engineering Girls Future Empowerment Program national final"}, "id": "104"}, {"text": {"en": "Read the project brief ", "zh": "阅读项目概要 "}, "attrs": {"href": {"en": "project-brief-en.html", "zh": "bp.html"}}, "id": "109"}, {"text": {"en": "Try the three-interface prototype ", "zh": "体验三端原型 "}, "id": "110"}, {"attrs": {"data-caption": {"zh": "EYES SEE · 出行端原型", "en": "EYES SEE traveler prototype · Original material in Chinese"}}, "id": "111"}, {"attrs": {"alt": {"zh": "EYES SEE 出行端，路线风险查询原型", "en": "EYES SEE traveler prototype with route risk information (Chinese source)"}}, "id": "112"}, {"text": {"en": "Traveler interface", "zh": "出行端"}, "id": "113"}, {"attrs": {"data-caption": {"zh": "EYES SEE · 家属端原型", "en": "EYES SEE family prototype · Original material in Chinese"}}, "id": "114"}, {"attrs": {"alt": {"zh": "EYES SEE 家属端，同行守护原型", "en": "EYES SEE family support prototype (Chinese source)"}}, "id": "115"}, {"text": {"en": "Family interface", "zh": "家属端"}, "id": "116"}, {"attrs": {"data-caption": {"zh": "EYES SEE · 治理端原型", "en": "EYES SEE administration prototype · Original material in Chinese"}}, "id": "117"}, {"attrs": {"alt": {"zh": "EYES SEE 治理端，道路风险与设施治理原型", "en": "EYES SEE administration prototype for road risks and facilities (Chinese source)"}}, "id": "118"}, {"text": {"en": "Enlarge the administration interface ↗", "zh": "点击放大治理端 ↗"}, "id": "119"}, {"text": {"en": "Desktop tool · Built with AI", "zh": "桌面工具 · AI 协作开发"}, "id": "120"}, {"text": {"en": "Good Time", "zh": "Good Time · 好时光"}, "id": "121"}, {"text": {"en": "Track your time.", "zh": "记录时间，"}, "id": "122"}, {"tail": {"en": " Keep your focus.", "zh": " 少打断一点。"}, "id": "123"}, {"text": {"en": "While studying and working remotely, I wanted to record time without repeatedly opening a spreadsheet. I built a desktop task timer to make records available for later review.", "zh": "学习和远程实习时，我想记录时间，又不想反复打开表格。于是做了一个桌面常驻的任务计时工具，用记录支持复盘。"}, "id": "124"}, {"text": {"en": "Download the desktop app ", "zh": "下载桌面应用 "}, "id": "125"}, {"text": {"en": "GOOD TIME", "zh": "GOOD TIME / 好时光"}, "id": "126"}, {"text": {"en": "Desktop time tracker", "zh": "桌面计时工具"}, "id": "127"}, {"attrs": {"aria-label": {"zh": "放大查看好时光桌面悬浮记录功能示意", "en": "Enlarge Good Time desktop timer illustration, not an app screenshot"}, "data-caption": {"zh": "好时光 · 桌面悬浮记录功能示意（非应用实拍）", "en": "Good Time desktop timer illustration, not an app screenshot · Original material in Chinese"}}, "id": "128"}, {"attrs": {"alt": {"zh": "好时光功能示意：桌面显示当前计时，可快速开始、切换任务、暂停或结束", "en": "Good Time timer feature illustration, not an application screenshot (Chinese source)"}}, "id": "129"}, {"text": {"en": "Start recording quickly. Review your time later.", "zh": "轻量开始记录，把时间带回复盘"}, "id": "130"}, {"text": {"en": "Enlarge image", "zh": "放大图片"}, "attrs": {"data-caption": {"zh": "好时光 · 桌面悬浮记录功能示意（非应用实拍）", "en": "Good Time desktop timer illustration, not an app screenshot · Original material in Chinese"}}, "id": "131"}, {"text": {"en": "Company survival game · Created with AI", "zh": "公司生存游戏 · AI 协作制作"}, "id": "132"}, {"text": {"en": "Thirty Days to Save the Company", "zh": "公司还有三十天倒闭"}, "id": "133"}, {"text": {"en": "A tabletop game about", "zh": "在桌游中体验"}, "id": "134"}, {"tail": {"en": " real workplace trade-offs", "zh": " 职场中的真实博弈"}, "id": "135"}, {"text": {"en": "Finance is hiding unpaid taxes. Engineering knows the system could fail. The CEO has a personal exit condition. Play a partner, allocate budgets and negotiate signatures through ten rounds of crises. Will you protect the company or yourself?", "zh": "财务藏着税务欠款，技术知道系统随时会崩，CEO 有自己的离场条件。你将扮演一位合伙人，在十轮危机中分配预算、争取签字，决定保住公司还是保住自己。"}, "id": "136"}, {"text": {"en": "Play the game (Chinese) ", "zh": "进入游戏试玩 "}, "id": "137"}, {"attrs": {"aria-label": {"zh": "开始游玩《三十天救公司》", "en": "Play Thirty Days to Save the Company in Chinese"}}, "id": "138"}, {"text": {"en": "Internal emergency notice / Partners only", "zh": "内部紧急通知 / 仅限合伙人"}, "id": "139"}, {"text": {"en": "The company has", "zh": "公司还有"}, "id": "140"}, {"tail": {"en": " days left", "zh": " 天"}, "id": "141"}, {"text": {"en": "Everyone has a secret.", "zh": "每个人都有秘密。"}, "id": "142"}, {"tail": {"en": " Every signature has a price.", "zh": " 每次签字都有代价。"}, "id": "143"}, {"text": {"en": "Become a partner (Chinese) ↗", "zh": "签下合伙人协议 ↗"}, "id": "144"}, {"text": {"en": "Operations & Content", "zh": "运营与内容"}, "id": "145"}, {"text": {"en": "Content creation & Brand collaboration", "zh": "内容创作与品牌合作"}, "id": "146"}, {"text": {"en": "Oct 2023 — Present", "zh": "2023.10 — 至今"}, "id": "147"}, {"text": {"en": "From putting thoughts into words", "zh": "从一次表达，"}, "id": "148"}, {"tail": {"en": " to being seen and heard.", "zh": " 到被看见、被回应。"}, "id": "149"}, {"text": {"en": "I write for WeChat and Xiaohongshu. A collaboration with driving-test platform Jiakaobaodian involved clarifying the brief, agreeing on content, producing and publishing it, and following up on feedback.", "zh": "持续创作公众号与小红书内容，并获得驾考宝典品牌合作机会，参与需求沟通、内容方案确认、制作发布与后续反馈。"}, "id": "150"}, {"text": {"en": "WeChat articles published", "zh": "公众号累计内容"}, "id": "151"}, {"text": {"en": "Highest views on a WeChat article", "zh": "公众号单篇最高阅读"}, "id": "152"}, {"text": {"en": "K+", "zh": "万+"}, "id": "153"}, {"text": {"en": "Highest views on a Xiaohongshu post", "zh": "小红书单篇最高浏览"}, "id": "154"}, {"attrs": {"data-caption": {"zh": "公众号 · 创作与互动记录", "en": "WeChat publishing and interaction records · Original material in Chinese"}}, "id": "155"}, {"attrs": {"alt": {"zh": "公众号创作、收藏、分享与留言记录", "en": "WeChat publishing and audience interaction evidence (Chinese source)"}}, "id": "156"}, {"attrs": {"data-caption": {"zh": "小红书 · 原有内容与浏览记录", "en": "Xiaohongshu content and view records · Original material in Chinese"}}, "id": "157"}, {"attrs": {"alt": {"zh": "小红书内容与浏览记录", "en": "Xiaohongshu post and view-count evidence (Chinese source)"}}, "id": "158"}, {"text": {"en": "Visit Xiaohongshu ↗", "zh": "去小红书看看 ↗"}, "id": "159"}, {"text": {"en": "WeChat account QR code", "zh": "查看公众号二维码"}, "attrs": {"data-caption": {"zh": "微信公众号二维码", "en": "WeChat account QR code · Original material in Chinese"}}, "id": "160"}, {"text": {"en": "User operations & AI workflows", "zh": "用户运营与 AI 工作流"}, "id": "161"}, {"text": {"en": "Turn everyday conversations", "zh": "把一次次沟通，"}, "id": "162"}, {"tail": {"en": " into methods others can reuse.", "zh": " 沉淀成可复用的方法。"}, "id": "163"}, {"text": {"en": "K+ RMB", "zh": "万+"}, "id": "164"}, {"text": {"en": "Revenue contributed from English courses", "zh": "英语长期班累计营收贡献"}, "id": "165"}, {"tail": {"en": " Approximately 180 paying learners", "zh": " 累计转化 180 名付费学员"}, "id": "166"}, {"text": {"en": "I segment users by year of study, current ability, commitment and goals, then adapt follow-up and address concerns about price, alternatives and refunds.", "zh": "围绕用户年级、基础、投入度和目标进行分层，按状态调整沟通重点与跟进节奏，处理价格、竞品、退款等不同异议。"}, "id": "167"}, {"text": {"en": "Eight AI assistants for specific workflows", "zh": "8 个垂直场景 AI 智能体"}, "id": "168"}, {"text": {"en": "I organized research, user feedback, case matching and reply preparation into reusable workflows, then shared the methods with a team of over 60.", "zh": "把专业调研、用户反馈提炼、案例匹配和回信辅助整理为可复用场景，方法同步至 60+ 人团队。"}, "id": "169"}, {"text": {"en": "View the AI workflow examples ", "zh": "查看 AI 工作流产出 "}, "attrs": {"data-caption": {"zh": "原有材料 · 垂直场景 AI 智能体", "en": "AI assistants and reusable workflows · Original material in Chinese"}}, "id": "170"}, {"text": {"en": "Experience", "zh": "实习经历"}, "id": "171"}, {"text": {"en": "Print / Save color PDF ↗", "zh": "打印／保存彩色 PDF ↗"}, "id": "172"}, {"text": {"en": "AI Data Intern", "zh": "AI 数据实习生"}, "id": "173"}, {"text": {"en": "Zhipu AI", "zh": "北京智谱华章科技股份有限公司"}, "id": "174"}, {"text": {"en": "Complex sample evaluation / Error analysis", "zh": "复杂样本评估 / Bad Case 归纳"}, "id": "175"}, {"text": {"en": "Expand ↓", "zh": "展开 ↓"}, "id": "176"}, {"text": {"en": "Collapse ↑", "zh": "收起 ↑"}, "id": "177"}, {"text": {"en": "Evaluated complex real-user question-and-answer samples, identified recurring issues and reported internal tool feedback, producing reviewable judgments under shared guidelines.", "zh": "围绕大模型真实用户问答质量，负责复杂样本评估、典型问题归纳和系统使用反馈，在统一规则下持续输出可复核判断。"}, "id": "178"}, {"text": {"en": "Checked logical consistency, plausibility and formatting; documented contradictions and recurring errors in structured feedback, developing a practical understanding of model limits.", "zh": "依据逻辑一致性、内容合理性和格式规范识别前后矛盾及不合常理问题，归纳典型 Bad Case，提交结构化反馈，积累对模型能力边界与易错类型的认识。"}, "id": "179"}, {"text": {"en": "User Operations Intern", "zh": "用户运营实习生"}, "id": "180"}, {"text": {"en": "Zhecai Xuezi Education Consulting", "zh": "杭州浙才学子教育咨询服务有限公司"}, "id": "181"}, {"text": {"en": "User segmentation / Conversion / AI workflows", "zh": "用户分层 / 转化 / AI 流程沉淀"}, "id": "182"}, {"text": {"en": "Expand ↓", "zh": "展开 ↓"}, "id": "183"}, {"text": {"en": "Collapse ↑", "zh": "收起 ↑"}, "id": "184"}, {"text": {"en": "Screened potential learners, handled consultations and follow-up, and supported purchases of English courses priced around RMB 4,000. Converted approximately 180 paying learners and contributed over RMB 700,000 in revenue.", "zh": "负责约 4000 元英语长期班的潜在用户筛选、商务沟通、关系维护与成交推进，累计转化 180 名付费学员、贡献 70 万元+营收。"}, "id": "185"}, {"text": {"en": "Segmented users by year of study, ability, commitment and goals. Adapted follow-up and increased conversions in a single sales round from two to nine. Addressed price, competitor and refund concerns, re-engaged past leads and achieved the top result in one sales round.", "zh": "按年级、基础、投入度和目标判断意向，调整跟进节奏，单轮成交由 2 单提升至 9 单；处理价格、竞品及退款等异议，盘活历史用户，推动单轮业绩团队第一。"}, "id": "186"}, {"text": {"en": "Created eight AI assistants for specific workflows. Methods were shared with a team of over 60 and incorporated into onboarding.", "zh": "创建 8 个垂直场景 AI 智能体，相关方法同步至 60+ 人团队并纳入新人培训。"}, "id": "187"}, {"text": {"en": "Event Operations Intern", "zh": "活动运营实习生"}, "id": "188"}, {"text": {"en": "Shanghai Jiedian Education Technology", "zh": "上海界点教育科技有限公司"}, "id": "189"}, {"text": {"en": "Eight events / 250+ participants per event", "zh": "8 场活动 / 单场 250+ 人"}, "id": "190"}, {"text": {"en": "Expand ↓", "zh": "展开 ↓"}, "id": "191"}, {"text": {"en": "Collapse ↑", "zh": "收起 ↑"}, "id": "192"}, {"text": {"en": "Helped organize eight online events for university students, each with over 250 participants, supporting recruitment, onboarding, live interaction and follow-up.", "zh": "参与大学生线上活动招募、用户承接、现场互动及转化跟进，共创 8 场单场 250+ 人线上活动。"}, "id": "193"}, {"text": {"en": "Invited participants through private channels, managed group entry and reminders, and served as an event coach for interaction, speaking and participant support. Followed up on participation and feedback.", "zh": "通过私域渠道完成邀约、入群与活动提醒，担任活动教练，负责现场互动、公开表达及过程陪伴，并跟进参与情况与用户反馈。"}, "id": "194"}, {"text": {"en": "ABOUT", "zh": "ABOUT / 关于我"}, "id": "195"}, {"text": {"en": "Think it through.", "zh": "想清楚一点，"}, "id": "196"}, {"tail": {"en": " Then take the next step.", "zh": " 再向前做一步。"}, "id": "197"}, {"text": {"en": "I’m Yuqing Mao, an automation undergraduate graduating in 2027. I start with real problems and turn loosely defined needs into projects people can see and try.", "zh": "我是毛雨晴，2027 届自动化技术与应用本科生。我习惯从真实问题出发，把零散需求推进为可以演示、可以验证的项目。"}, "id": "198"}, {"text": {"en": "My work spans user communication, product planning, teamwork and development with AI. Feedback has changed my decisions along the way. Continuing to improve after building matters just as much to me.", "zh": "我做过用户沟通、方案设计、团队协作、AI 辅助开发，也在现场反馈里修改过自己的判断。对我来说，做出来之后愿意继续改，是同样重要的一步。"}, "id": "199"}, {"text": {"en": "Nanjing Vocational University of Industry Technology", "zh": "南京工业职业技术大学"}, "id": "200"}, {"text": {"en": "Bachelor’s in Automation Technology and Applications · Sep 2023–Jun 2027", "zh": "自动化技术与应用专业（本科） · 2023.09—2027.06"}, "id": "201"}, {"text": {"en": "CET-4: 577 / CET-6 · National Computer Rank Examination Level 2 (MS Office)", "zh": "CET-4 577 / CET-6 · 全国计算机二级（MS Office）"}, "id": "202"}, {"tail": {"en": " Academic scholarships for two consecutive years", "zh": " 连续两年获得学业奖学金"}, "id": "203"}, {"text": {"en": "Where I’ve used these tools", "zh": "这些工具，我用在了哪里"}, "id": "204"}, {"text": {"en": "Built Good Time with AI, including a floating desktop timer, and released Mac and Windows packages.", "zh": "通过 AI 协作开发好时光，做出桌面悬浮计时卡片，并发布 Mac 和 Windows 安装包。"}, "id": "205"}, {"text": {"en": "Built GLIM’s backend, including sign-in, storage and data access controls.", "zh": "在碰见项目中搭建后端，处理用户登录和数据存储，并设置数据访问权限。"}, "id": "206"}, {"text": {"en": "Excel / Feishu", "zh": "Excel / 飞书"}, "id": "207"}, {"text": {"en": "Organized outreach and course-conversion records, reviewed responses to different messages, and documented follow-up methods for the team.", "zh": "整理用户触达和课程转化记录，复盘不同话术的反馈，并把跟进方法整理给团队使用。"}, "id": "208"}, {"text": {"en": "LET’S TALK", "zh": "LET’S TALK / 联系我"}, "id": "209"}, {"text": {"en": "Have a real problem in mind?", "zh": "有一个真实问题，"}, "id": "210"}, {"tail": {"en": " Let’s talk it through.", "zh": " 我们可以聊聊。"}, "id": "211"}, {"text": {"en": "Switch to dark mode", "zh": "切换深色"}, "id": "212"}, {"text": {"en": "Yuqing Mao · Portfolio 2026", "zh": "毛雨晴 · 2026 个人作品集"}, "id": "213"}, {"text": {"en": "Back to top ↑", "zh": "回到顶部 ↑"}, "id": "214"}, {"text": {"en": "Close ×", "zh": "关闭 ×"}, "attrs": {"aria-label": {"zh": "关闭图片", "en": "Close image"}}, "id": "215"}, {"attrs": {"alt": {"zh": "项目原图", "en": " · original project image"}}, "id": "216"}, {"id": "217", "text": {"en": "47", "zh": "4.7"}}, {"id": "218", "text": {"en": "700", "zh": "70"}}, {"id": "219", "text": {"zh": "绿色行动奖 · 陶氏 × 启创空间", "en": "Green Action Award · Dow × InnoSpace"}}, {"id": "220", "text": {"zh": "从出行者到家属，再到治理端，试着把出行中的信息接起来。", "en": "Connecting the traveler, family and administration perspectives on accessible travel."}}, {"id": "221", "text": {"zh": "桌面常驻计时，记录保存在本机。", "en": "A desktop timer with records stored locally."}}, {"id": "222", "text": {"zh": "解决", "en": "forward"}}, {"id": "223", "attrs": {"alt": {"zh": "社交电量灯", "en": "Social light"}}}, {"id": "224", "text": {"zh": "社交电量灯", "en": "Social light"}}, {"id": "225", "attrs": {"alt": {"zh": "互助信号", "en": "Help signal"}}}, {"id": "226", "text": {"zh": "互助信号", "en": "Help signal"}}, {"id": "227", "attrs": {"alt": {"zh": "AI 破冰", "en": "AI icebreakers"}}}, {"id": "228", "text": {"zh": "AI 破冰", "en": "AI icebreakers"}}, {"id": "229", "attrs": {"alt": {"zh": "AI 复盘", "en": "AI review"}}}, {"id": "230", "text": {"zh": "AI 复盘", "en": "AI review"}}];
(() => {
  const root = document.documentElement;
  const controls = [...document.querySelectorAll('[data-language-switch]')];
  let language = root.dataset.defaultLanguage || 'zh';
  const bindings = portfolioLanguages.map(record => ({record, element:document.querySelector(`[data-i18n="${record.id}"]`)}));
  function apply(next, preservePosition = true) {
    const candidates = [...document.querySelectorAll('section[id], article[id], footer')];
    const footer = document.querySelector('footer');
    const anchor = footer && footer.getBoundingClientRect().top < innerHeight ? footer : candidates.filter(el => el.getBoundingClientRect().top <= innerHeight / 3 && el.getBoundingClientRect().bottom > 0).at(-1);
    const before = anchor?.getBoundingClientRect().top;
    language = next; root.lang = next === 'zh' ? 'zh-CN' : 'en';
    bindings.forEach(({record,element}) => {
      if (!element) return;
      if (record.text && element.firstChild?.nodeType === Node.TEXT_NODE) element.firstChild.nodeValue = record.text[next];
      if (record.tail && element.nextSibling?.nodeType === Node.TEXT_NODE) element.nextSibling.nodeValue = record.tail[next];
      Object.entries(record.attrs || {}).forEach(([key,values]) => element.setAttribute(key, values[next]));
    });
    controls.forEach(button => {
      button.textContent = next === 'en' ? '切换中文' : '切换 English';
      const label = next === 'en' ? '切换中文' : '切换 English';
      button.setAttribute('aria-label',label); button.title = label;
    });
    if (typeof setTheme === 'function') setTheme(document.body.classList.contains('dark'));
    const dialog = document.getElementById('image-dialog');
    if (dialog?.open) {
      const expanded = document.getElementById('expanded-image');
      const trigger = [...document.querySelectorAll('[data-image]')].find(el => el.dataset.image === expanded.getAttribute('src'));
      if (trigger) { expanded.alt = trigger.dataset.caption || trigger.querySelector('img')?.alt || ''; document.getElementById('image-caption').textContent = expanded.alt; }
    }
    if (preservePosition && anchor) window.scrollBy({top:anchor.getBoundingClientRect().top - before,behavior:'instant'});
  }
  controls.forEach(button => button.addEventListener('click', () => apply(language === 'en' ? 'zh' : 'en')));
  apply(language, false);
})();
